package com.bank.eos.producer;

import java.util.HashMap;
import java.util.Map;

// Assigns the producer id and the per-partition sequence numbers.
public class ProducerSession {
    private final long producerId;
    private final Map<Integer, Long> nextSeq = new HashMap<>();

    public ProducerSession(long producerId) { this.producerId = producerId; }

    public long getProducerId() { return producerId; }

    // next sequence for a partition (idempotence tracks this per partition)
    public long nextSequence(int partition) {
        long seq = nextSeq.getOrDefault(partition, 0L);
        nextSeq.put(partition, seq + 1);
        return seq;
    }
}
