package com.bank.eos.broker;

import com.bank.eos.model.FeeEvent;
import java.util.*;

// Broker-side dedup by (producerId, partition) using the last accepted sequence.
public class IdempotentLog {
    private final Map<String, Long> lastSeq = new HashMap<>();
    private final List<FeeEvent> log = new ArrayList<>();

    // Returns true if newly appended; false if a duplicate retry was deduped.
    public boolean append(long producerId, int partition, long sequence, FeeEvent event) {
        String key = producerId + ":" + partition;
        long last = lastSeq.getOrDefault(key, -1L);
        if (sequence <= last) {
            return false; // duplicate retry -> ack but do not write again
        }
        if (sequence > last + 1) {
            throw new IllegalStateException("Out-of-order sequence: expected "
                + (last + 1) + " got " + sequence);
        }
        lastSeq.put(key, sequence);
        log.add(event);
        return true;
    }

    public List<FeeEvent> getLog() { return log; }
}
