package com.bank.eos.broker;

import com.bank.eos.model.FeeEvent;
import java.util.*;

// Composes idempotent writes + atomic commit of offset = exactly-once consume-process-produce.
public class ExactlyOnceUnit {
    private final IdempotentLog log;
    private long committedOffset = -1;
    private List<FeeEvent> pending;
    private long pendingOffset;

    public ExactlyOnceUnit(IdempotentLog log) { this.log = log; }

    public void begin(long offsetBeingProcessed) {
        pending = new ArrayList<>();
        pendingOffset = offsetBeingProcessed;
    }

    public void produce(long pid, int part, long seq, FeeEvent e) {
        log.append(pid, part, seq, e);   // idempotent write
        pending.add(e);
    }

    // Atomically: records already written + offset advanced together.
    public void commit() {
        committedOffset = pendingOffset;
        pending = null;
    }

    public void abort() { pending = null; } // offset NOT advanced -> reprocessed safely

    public long getCommittedOffset() { return committedOffset; }
}
