package com.bank.eos;

import com.bank.eos.broker.ExactlyOnceUnit;
import com.bank.eos.broker.IdempotentLog;
import com.bank.eos.model.FeeEvent;
import com.bank.eos.producer.ProducerSession;
import java.math.BigDecimal;
import java.util.logging.*;

public class EosDemo {
    private static final Logger log = Logger.getLogger(EosDemo.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        IdempotentLog broker = new IdempotentLog();
        ProducerSession session = new ProducerSession(777L);

        int partition = 2;
        long seq = session.nextSequence(partition); // 0
        FeeEvent fee = new FeeEvent("TRD-001", "CUR3001", new BigDecimal("125.00"));

        // First write succeeds, broker writes it.
        broker.append(session.getProducerId(), partition, seq, fee);
        // Ack lost -> producer retries SAME seq twice (idempotence dedups).
        boolean r1 = broker.append(session.getProducerId(), partition, seq, fee);
        boolean r2 = broker.append(session.getProducerId(), partition, seq, fee);
        log.info(() -> "Retries stored? " + r1 + "/" + r2 + " -> log size="
            + broker.getLog().size() + " (fee charged ONCE)");

        // Exactly-once consume-process-produce around offset 500.
        ExactlyOnceUnit unit = new ExactlyOnceUnit(broker);
        unit.begin(500);
        long s2 = session.nextSequence(partition); // 1
        unit.produce(session.getProducerId(), partition, s2,
            new FeeEvent("TRD-002", "SAV2001", new BigDecimal("80.00")));
        unit.commit();
        log.info("Committed offset=" + unit.getCommittedOffset()
            + ", total fees in log=" + broker.getLog().size());
    }
}

class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$-7s] %3$s%n",
            new java.util.Date(r.getMillis()), r.getLevel(), formatMessage(r));
    }
}
